def _print_results(results: Sequence[RankedResult]) -> None:
    if not results:
        print("  (no results)")
        return
    for r in results:
        md = r.chunk.metadata
        snippet = r.chunk.text.strip().replace("\n", " ")[:80]
        print(
            f"  #{r.rank + 1}  id={md.get('doc_id','-'):<22} score={r.score:+.4f} "
            f"cat={md.get('category','-'):<9} year={md.get('year','-')} "
            f"prio={md.get('priority','-'):<6} tags={','.join(md.get('tags', []) or [])}"
        )
        print(f"      {snippet}...")


