    print("=" * 78)
    print("Metadata-aware RAG demo")
    print("=" * 78)

    pipe = RAGPipeline(embedder=AutoEmbedder(prefer="hash"))
    print(f"\n[ingest] embedder backend: {pipe.embedder.backend}")
    n = pipe.index_documents(_demo_documents())
    print(f"[ingest] indexed {n} chunks from {len(pipe.store.chunks)} documents")

    print("\n--- 1. Metadata PRE-FILTERING: only category=docs is eligible ---")
    res = pipe.retrieve(
        "how do I configure API rate limits for my account?",
        k=3,
        metadata_filter={"category": "docs"},
    )
    _print_results(res)

    print("\n--- 2. RANGE filter (year >= 2023) on timeout question ---")
    res = pipe.retrieve(
        "what happens if my requests time out?",
        k=3,
        metadata_filter={"year": {"gte": 2023}},
    )
    _print_results(res)

    print("\n--- 3. Boolean filter: legal OR docs, excluding changelog ---")
    res = pipe.retrieve(
        "what do you do with my data?",
        k=3,
        metadata_filter={
            "$and": [
                {"category": {"in": ["legal", "docs"]}},
                {"category": {"neq": "changelog"}},
            ]
        },
    )
    _print_results(res)

    print("\n--- 4. METADATA RANKING: recency time-decay (2025 reference) ---")
    recency_config = RankConfig(
        fusion="rrf",
        time_decay=TimeDecay(field="published", reference="2025-06-01", half_life_days=365),
    )
    res = pipe.retrieve("rate limiting policy", k=3, rank_config=recency_config)
    _print_results(res)

    print("\n--- 5. METADATA RANKING: priority/tag boost rules ---")
    boost = MetadataBoost()
    boost.add_rule(eq("priority", "high"), 1.5)
    boost.add_rule(contains("tags", "search"), 1.3)
    boost_config = RankConfig(metadata_boost=boost)
    res = pipe.retrieve(
        "relevance ranking with metadata filters",
        k=3,
        rank_config=boost_config,
    )
    _print_results(res)

    print("\n--- 6. MMR diversity reranking (lambda=0.7) ---")
    res = pipe.retrieve(
        "api documentation webhooks and batching",
        k=3,
        mmr=MMRReranker(lambda_mult=0.7),
    )
    _print_results(res)

    print("\n--- 7. End-to-end grounded answer (with citations) ---")
    out = pipe.query(
        "how do I configure API rate limits for my account?",
        k=2,
        metadata_filter={"category": "docs"},
    )
    print(f"query: {out.query}")
    print(out.answer)

    print("\n--- 8. Evaluation (Hits@3 / MRR) ---")
    cases = [
        {"query": "how do I configure api rate limits", "relevant": ["rate-limits"],
         "filter": {"category": "docs"}},
        {"query": "what are the terms for data retention", "relevant": ["terms", "privacy"]},
        {"query": "timeout errors when calling the api", "relevant": ["timeouts"]},
        {"query": "how to set up webhooks", "relevant": ["webhooks"]},
        {"query": "rate limiting for eu customers", "relevant": ["rate-limit-incident"],
         "filter": {"region": "eu"}},
    ]
    metrics = evaluate(pipe, cases, k=3)
    print(f"  mean Hits@3 : {metrics['mean_hits_at_k']:.3f}")
    print(f"  mean MRR    : {metrics['mean_mrr']:.3f}")
    print(f"  mean latency: {metrics['mean_latency_seconds'] * 1000:.1f} ms")
    for case in metrics["cases"]:
        flag = "OK " if case["hits_at_k"] else "MISS"
        print(f"  [{flag}] {case['query']:<45} top={case['top_ids']}")


if __name__ == "__main__":
    main()

