"""Local, dependency-free embedding backend used by the RAG pipeline.

The pipeline only relies on the interface implemented here:

* ``fit(texts)``          - build the vocabulary / IDF table over the corpus
* ``embed_query(text)``   - vectorize a query
* ``embed_documents(list)`` - vectorize documents
* ``cosine(a, b)``        - similarity between two vectors

Swap this class for a production embedding model (OpenAI,
sentence-transformers, ...) behind the same interface without touching the
retrieval or ranking code (see rag_system/adapters.py).
"""
from __future__ import annotations

import math
import re
from collections import Counter
from typing import Dict, List, Tuple

TOKEN_RE = re.compile(r"[a-z0-9]+")
NON_ALNUM = re.compile(r"[^a-z0-9]")

STOPWORDS = frozenset({
    "a", "an", "the", "and", "or", "but", "if", "then", "else", "for", "of",
    "to", "in", "on", "at", "by", "with", "from", "as", "is", "are", "was",
    "were", "be", "been", "being", "have", "has", "had", "do", "does", "did",
    "will", "would", "can", "could", "should", "shall", "may", "might", "must",
    "this", "that", "these", "those", "it", "its", "we", "our", "you", "your",
    "they", "their", "he", "she", "him", "her", "i", "not", "no", "yes", "all",
    "any", "each", "every", "both", "more", "most", "other", "some", "such",
    "only", "own", "same", "than", "too", "very", "so", "also", "when", "where",
    "which", "who", "whom", "what", "how", "why", "about", "into", "over",
    "after", "before", "between", "under", "during", "within", "without",
    "against", "upon", "per", "via", "etc", "eg", "ie", "e.g", "i.e", "1", "2",
    "3", "4", "5", "6", "7", "8", "9", "0",
})


def stem(token: str) -> str:
    """Lightweight suffix stripper so that 'rotate'/'rotated' and
    'account'/'accounts' compare equal during retrieval / answering."""
    if len(token) <= 4:
        return token
    for suffix in ("ing", "ed", "es", "s"):
        if token.endswith(suffix) and len(token) - len(suffix) >= 3:
            token = token[: -len(suffix)]
            break
    if token.endswith("e") and len(token) >= 5 and token[-2] not in "aeiou":
        token = token[:-1]
    return token


def tokenize(text: str) -> List[str]:
    """Lower-cased, stop-word-filtered, stemmed tokens."""
    return [stem(t) for t in TOKEN_RE.findall(text.lower())
            if t not in STOPWORDS and len(t) > 1]


class LocalVectorizer:
    """TF-IDF vectorizer with character n-grams.

    Produces sparse, L2-normalized vectors as ``{feature: weight}`` dicts.
    Character n-grams add a light form of fuzzy matching (misspellings and
    morphological variants) on top of the token features.
    """

    def __init__(self, use_char_ngrams: bool = True,
                 ngram_range: Tuple[int, int] = (2, 3),
                 min_df: int = 1):
        self.use_char_ngrams = use_char_ngrams
        self.ngram_range = ngram_range
        self.min_df = min_df
        self.vocab: Dict[str, int] = {}
        self.idf: Dict[str, float] = {}
        self.n_docs = 0

    # -- feature extraction ------------------------------------------------
    def _features(self, text: str) -> Counter:
        feats: Counter = Counter()
        feats.update(tokenize(text))
        if self.use_char_ngrams:
            cleaned = NON_ALNUM.sub("", text.lower())
            for n in range(self.ngram_range[0], self.ngram_range[1] + 1):
                for i in range(len(cleaned) - n + 1):
                    gram = cleaned[i:i + n]
                    if gram.isdigit():      # skip pure numeric grams
                        continue
                    feats[gram] += 1
        return feats

    # -- fit / transform ---------------------------------------------------
    def fit(self, texts: List[str]) -> "LocalVectorizer":
        self.n_docs = len(texts)
        df: Counter = Counter()
        for text in texts:
            for feat in self._features(text):
                df[feat] += 1
        self.vocab = {f: i for i, f in enumerate(
            sorted(f for f, d in df.items() if d >= self.min_df)
        )}
        self.idf = {
            f: math.log((self.n_docs + 1) / (d + 1)) + 1.0
            for f, d in df.items() if f in self.vocab
        }
        return self

    def transform(self, text: str) -> Dict[str, float]:
        weights: Dict[str, float] = {}
        for feat, count in self._features(text).items():
            idf = self.idf.get(feat)
            if idf is None:
                continue
            weights[feat] = count * idf
        norm = math.sqrt(sum(v * v for v in weights.values()))
        if norm:
            weights = {f: v / norm for f, v in weights.items()}
        return weights

    @staticmethod
    def cosine(a: Dict[str, float], b: Dict[str, float]) -> float:
        """Cosine similarity between two normalized sparse vectors."""
        if not a or not b:
            return 0.0
        if len(a) > len(b):
            a, b = b, a
        dot = 0.0
        for feat, weight in a.items():
            other = b.get(feat)
            if other:
                dot += weight * other
        return dot


class LocalEmbeddings:
    """Uniform embedding interface backed by :class:`LocalVectorizer`."""

    def __init__(self, **vectorizer_kwargs):
        self.vectorizer = LocalVectorizer(**vectorizer_kwargs)
        self._fitted = False

    def fit(self, texts: List[str]) -> None:
        self.vectorizer.fit(texts)
        self._fitted = True

    def embed_query(self, text: str) -> Dict[str, float]:
        if not self._fitted:
            raise RuntimeError("Call fit() with the corpus before embedding.")
        return self.vectorizer.transform(text)

    def embed_documents(self, texts: List[str]) -> List[Dict[str, float]]:
        if not self._fitted:
            raise RuntimeError("Call fit() with the corpus before embedding.")
        return [self.vectorizer.transform(t) for t in texts]

    def cosine(self, a: Dict[str, float], b: Dict[str, float]) -> float:
        return self.vectorizer.cosine(a, b)

"""Recursive character-level chunking with configurable overlap."""
from __future__ import annotations

from typing import List, Optional

from .models import Chunk, Document

DEFAULT_SEPARATORS = ["\n\n", "\n", ". ", " "]


class RecursiveChunker:
    """Splits text by progressively finer separators, then applies overlap.

    ``chunk_size`` is the target maximum length in characters; chunks carry
    ``chunk_overlap`` characters of the previous chunk so context is not cut
    at boundaries.
    """

    def __init__(self, chunk_size: int = 800, chunk_overlap: int = 120,
                 separators: Optional[List[str]] = None):
        if chunk_overlap >= chunk_size:
            raise ValueError("chunk_overlap must be smaller than chunk_size")
        self.chunk_size = chunk_size
        self.chunk_overlap = chunk_overlap
        self.separators = separators or list(DEFAULT_SEPARATORS)

    # -- public API --------------------------------------------------------
    def split(self, text: str) -> List[str]:
        if not text:
            return []
        raw = self._split_recursive(text.strip())
        return self._apply_overlap(raw)

    def chunk_document(self, doc: Document) -> List[Chunk]:
        chunks: List[Chunk] = []
        for idx, part in enumerate(self.split(doc.text)):
            chunks.append(Chunk(
                id=f"{doc.id}::chunk-{idx:03d}",
                text=part,
                doc_id=doc.id,
                metadata=dict(doc.metadata),
                chunk_index=idx,
            ))
        return chunks

    # -- internals ---------------------------------------------------------
    def _split_recursive(self, text: str) -> List[str]:
        if len(text) <= self.chunk_size:
            return [text]
        for sep in self.separators:
            if sep in text:
                pieces: List[str] = []
                current = ""
                for part in text.split(sep):
                    candidate = (current + sep + part).strip() if current else part.strip()
                    if current and len(candidate) > self.chunk_size:
                        pieces.append(current)
                        current = part.strip()
                    else:
                        current = candidate
                if current:
                    pieces.append(current)
                merged: List[str] = []
                for piece in pieces:
                    if len(piece) > self.chunk_size:
                        merged.extend(self._hard_split(piece))
                    else:
                        merged.append(piece)
                return merged
        return self._hard_split(text)

    def _hard_split(self, text: str) -> List[str]:
        step = max(1, self.chunk_size - self.chunk_overlap)
        return [text[i:i + self.chunk_size] for i in range(0, len(text), step)]

    def _apply_overlap(self, segments: List[str]) -> List[str]:
        if self.chunk_overlap <= 0 or len(segments) <= 1:
            return segments
        result: List[str] = []
        for i, seg in enumerate(segments):
            text = seg
            if i > 0:
                tail = segments[i - 1][-self.chunk_overlap:].strip()
                if tail:
                    text = tail + "\n" + seg
            result.append(text)
        return result

"""Metadata filter expressions used for pre-retrieval filtering.

Filters operate on a document / chunk metadata dictionary and support both
atomic field comparisons and boolean combinations (AND / OR / NOT), so
retrieval can be restricted *before* relevance ranking happens.
"""
from __future__ import annotations

import operator
from typing import Any, Dict, List, Optional, Union


def _as_number(value: Any) -> Optional[float]:
    if isinstance(value, bool):
        return None
    if isinstance(value, (int, float)):
        return float(value)
    if isinstance(value, str):
        try:
            return float(value)
        except (TypeError, ValueError):
            return None
    return None


def _loose_equal(a: Any, b: Any) -> bool:
    """Equality that also treats numeric strings and numbers as equal."""
    na, nb = _as_number(a), _as_number(b)
    if na is not None and nb is not None:
        return na == nb
    return a == b


class Filter:
    """Base class. Subclasses implement ``matches(metadata) -> bool``."""

    def matches(self, metadata: Dict[str, Any]) -> bool:
        raise NotImplementedError

    def __and__(self, other: "Filter") -> "And":
        return And(self, other)

    def __or__(self, other: "Filter") -> "Or":
        return Or(self, other)

    def __invert__(self) -> "Not":
        return Not(self)

    def __repr__(self) -> str:
        return self.__class__.__name__


class FieldFilter(Filter):
    """Compare one metadata field with a value.

    Operators: eq, ne, gt, gte, lt, lte, in, not_in, contains,
    exists, not_exists.
    """

    _COMPARATORS = {
        "gt": operator.gt,
        "gte": operator.ge,
        "lt": operator.lt,
        "lte": operator.le,
    }

    def __init__(self, field: str, op: str, value: Any = None):
        self.field = field
        self.op = op
        self.value = value

    def matches(self, metadata: Dict[str, Any]) -> bool:
        if self.op == "exists":
            return self.field in metadata and metadata[self.field] is not None
        if self.op == "not_exists":
            return not (self.field in metadata and metadata[self.field] is not None)

        if self.field not in metadata or metadata[self.field] is None:
            return False
        actual = metadata[self.field]

        if self.op == "eq":
            return _loose_equal(actual, self.value)
        if self.op == "ne":
            return not _loose_equal(actual, self.value)
        if self.op == "in":
            return self.value is not None and any(
                _loose_equal(actual, v) for v in self.value
            )
        if self.op == "not_in":
            return self.value is None or not any(
                _loose_equal(actual, v) for v in self.value
            )
        if self.op == "contains":
            if isinstance(actual, (list, tuple, set)):
                return any(str(self.value) in str(item) for item in actual)
            return str(self.value) in str(actual)
        if self.op in self._COMPARATORS:
            na, nb = _as_number(actual), _as_number(self.value)
            if na is None or nb is None:
                return False
            return self._COMPARATORS[self.op](na, nb)
        raise ValueError(f"Unknown filter operator: {self.op!r}")

    def __repr__(self) -> str:
        if self.op in ("exists", "not_exists"):
            return f"{self.op}({self.field!r})"
        return f"{self.field} {self.op} {self.value!r}"


class And(Filter):
    def __init__(self, *filters: Filter):
        self.filters = list(filters)

    def matches(self, metadata: Dict[str, Any]) -> bool:
        return all(f.matches(metadata) for f in self.filters)

    def __repr__(self) -> str:
        return "(" + " AND ".join(repr(f) for f in self.filters) + ")"


class Or(Filter):
    def __init__(self, *filters: Filter):
        self.filters = list(filters)

    def matches(self, metadata: Dict[str, Any]) -> bool:
        return any(f.matches(metadata) for f in self.filters)

    def __repr__(self) -> str:
        return "(" + " OR ".join(repr(f) for f in self.filters) + ")"


class Not(Filter):
    def __init__(self, inner: Filter):
        self.inner = inner

    def matches(self, metadata: Dict[str, Any]) -> bool:
        return not self.inner.matches(metadata)

    def __repr__(self) -> str:
        return f"NOT {self.inner!r}"


def from_dict(spec: Union[Dict[str, Any], List[Dict[str, Any]]]) -> Filter:
    """Build a filter from a declarative spec.

    Examples::

        {"category": {"eq": "security"}}
        [{"category": {"in": ["security", "compliance"]}},
         {"year": {"gte": 2023}}]                       # AND
        {"or": [{"category": {"eq": "security"}},
                {"priority": {"eq": "high"}}]}
        {"not": {"status": {"eq": "draft"}}}
        {"year": {"op": "gte", "value": 2023}}          # explicit form
    """
    if isinstance(spec, dict) and len(spec) == 1:
        key, value = next(iter(spec.items()))
        if key in ("and", "or", "not"):
            if key == "and":
                return And(*[from_dict(s) for s in value])
            if key == "or":
                return Or(*[from_dict(s) for s in value])
            return Not(from_dict(value))
        if isinstance(value, dict):
            op = value.get("op") or next(iter(value))
            operand = value.get("value", value[op] if op in value else None)
            return FieldFilter(key, op, operand)
    if isinstance(spec, list):
        return And(*[from_dict(s) for s in spec])
    raise ValueError(f"Invalid filter spec: {spec!r}")

"""Chunk store supporting metadata-filtered dense similarity search."""
from __future__ import annotations

from typing import Dict, List, Optional, Tuple

from .embeddings import LocalEmbeddings
from .filters import Filter
from .models import Chunk


class VectorStore:
    """Holds chunks + their embedding vectors; applies metadata filters
    before ranking candidates."""

    def __init__(self, embeddings: LocalEmbeddings):
        self.embeddings = embeddings
        self.chunks: List[Chunk] = []
        self.vectors: List[Dict[str, float]] = []

    def rebuild(self, chunks: List[Chunk],
                embeddings: Optional[LocalEmbeddings] = None) -> None:
        if embeddings is not None:
            self.embeddings = embeddings
        self.chunks = list(chunks)
        self.vectors = self.embeddings.embed_documents([c.text for c in chunks])

    def matching_indices(self, filter_expr: Optional[Filter]) -> List[int]:
        """Indices of chunks whose metadata passes the filter."""
        if filter_expr is None:
            return list(range(len(self.chunks)))
        return [i for i, c in enumerate(self.chunks) if filter_expr.matches(c.metadata)]

    def dense_scores(self, query: str, indices: List[int]) -> Dict[int, float]:
        qv = self.embeddings.embed_query(query)
        return {i: self.embeddings.cosine(qv, self.vectors[i]) for i in indices}

    def similarity_search(self, query: str, k: int = 5,
                          filter_expr: Optional[Filter] = None
                          ) -> List[Tuple[Chunk, float]]:
        """Pure dense retrieval over the filtered candidate pool."""
        indices = self.matching_indices(filter_expr)
        scored = sorted(self.dense_scores(query, indices).items(),
                        key=lambda kv: kv[1], reverse=True)
        return [(self.chunks[i], s) for i, s in scored[:k]]

    def mmr_search(self, query: str, k: int = 5, fetch_k: int = 20,
                   lambda_mult: float = 0.5,
                   filter_expr: Optional[Filter] = None
                   ) -> List[Tuple[Chunk, float]]:
        """Maximal Marginal Relevance: relevance + diversity trade-off."""
        qv = self.embeddings.embed_query(query)
        indices = self.matching_indices(filter_expr)
        scored = [(i, self.embeddings.cosine(qv, self.vectors[i])) for i in indices]
        scored.sort(key=lambda x: x[1], reverse=True)
        candidates = scored[:fetch_k]
        selected: List[Tuple[int, float]] = []
        while candidates and len(selected) < k:
            best_idx, best_score, best_mmr = None, None, float("-inf")
            for i, s in candidates:
                if selected:
                    max_sim = max(
                        self.embeddings.cosine(self.vectors[i], self.vectors[j])
                        for j, _ in selected
                    )
                else:
                    max_sim = 0.0
                mmr = lambda_mult * s - (1.0 - lambda_mult) * max_sim
                if mmr > best_mmr:
                    best_mmr, best_idx, best_score = mmr, i, s
            candidates = [c for c in candidates if c[0] != best_idx]
            selected.append((best_idx, best_score))
        return [(self.chunks[i], s) for i, s in selected]

"""Relevance ranking: hybrid retrieval + metadata-based reranking.

* :class:`HybridRetriever` fuses dense (vector) and sparse (BM25) scores
  over the metadata-filtered candidate pool.
* :class:`MetadataReranker` adds metadata-derived relevance boosts
  (recency, priority, explicit field values) on top of the base score.
* :class:`MMRReranker` trades a little relevance for topical diversity.
"""
from __future__ import annotations

from typing import Dict, List, Optional, Tuple

from .bm25 import BM25Index
from .filters import Filter
from .models import Chunk
from .store import VectorStore


class HybridRetriever:
    """Fuses dense and sparse relevance scores over a filtered pool."""

    def __init__(self, vectorstore: VectorStore, bm25: BM25Index,
                 dense_weight: float = 0.6, sparse_weight: float = 0.4):
        if dense_weight < 0 or sparse_weight < 0:
            raise ValueError("weights must be non-negative")
        self.vectorstore = vectorstore
        self.bm25 = bm25
        self.dense_weight = dense_weight
        self.sparse_weight = sparse_weight

    @staticmethod
    def _minmax(scores: Dict[int, float]) -> Dict[int, float]:
        """Min-max normalize per arm so dense and sparse are comparable."""
        if not scores:
            return scores
        lo, hi = min(scores.values()), max(scores.values())
        if hi == lo:
            return {i: 0.0 for i in scores} if lo == 0.0 else {i: 1.0 for i in scores}
        return {i: (v - lo) / (hi - lo) for i, v in scores.items()}

    def retrieve(self, query: str, k: int = 5,
                 filter_expr: Optional[Filter] = None
                 ) -> List[Tuple[Chunk, float, float, float]]:
        """Returns ``(chunk, fused_score, dense_score, sparse_score)`` desc.

        The metadata filter restricts the candidate pool *before* scoring.
        """
        indices = self.vectorstore.matching_indices(filter_expr)
        dense = self.vectorstore.dense_scores(query, indices)
        sparse_raw = self.bm25.score(query)
        sparse = {i: sparse_raw[i] for i in indices}
        dense_n = self._minmax(dense)
        sparse_n = self._minmax(sparse)
        fused = {
            i: (self.dense_weight * dense_n.get(i, 0.0)
                + self.sparse_weight * sparse_n.get(i, 0.0))
            for i in indices
        }
        ranked = sorted(fused.items(), key=lambda kv: kv[1], reverse=True)[:k]
        return [(self.vectorstore.chunks[i], fused[i], dense_n[i], sparse_n[i])
                for i, _ in ranked]


# --------------------------------------------------------------------------
# Metadata-based ranking signals
# --------------------------------------------------------------------------
class MetadataBooster:
    """Base class: returns a relevance bonus for a chunk's metadata."""

    def boost(self, metadata: Dict) -> float:
        raise NotImplementedError

    def label(self) -> str:
        return self.__class__.__name__


class RecencyBooster(MetadataBooster):
    """Boosts newer documents (numeric field such as ``year``)."""

    def __init__(self, field: str = "year", max_boost: float = 0.12,
                 max_age: int = 10, reference_year: float = 2025.0):
        self.field = field
        self.max_boost = max_boost
        self.max_age = max_age
        self.reference_year = reference_year

    def boost(self, metadata: Dict) -> float:
        try:
            year = float(metadata.get(self.field))
        except (TypeError, ValueError):
            return 0.0
        age = max(0.0, self.reference_year - year)
        if age >= self.max_age:
            return 0.0
        return self.max_boost * (1.0 - age / self.max_age)

    def label(self) -> str:
        return f"recency({self.field})"


class PriorityBooster(MetadataBooster):
    """Boosts chunks whose ``priority`` field maps to a configured bonus."""

    _DEFAULT = {"high": 0.15, "medium": 0.06, "low": 0.0}

    def __init__(self, field: str = "priority",
                 mapping: Optional[Dict[str, float]] = None):
        self.field = field
        self.mapping = mapping or dict(self._DEFAULT)

    def boost(self, metadata: Dict) -> float:
        return float(self.mapping.get(str(metadata.get(self.field, "")).lower(), 0.0))

    def label(self) -> str:
        return f"priority({self.field})"


class FieldValueBooster(MetadataBooster):
    """Generic booster: adds ``bonus`` when ``metadata[field] == value``."""

    def __init__(self, field: str, value, bonus: float,
                 label: Optional[str] = None):
        self.field = field
        self.value = value
        self.bonus = bonus
        self._label = label

    def boost(self, metadata: Dict) -> float:
        return self.bonus if metadata.get(self.field) == self.value else 0.0

    def label(self) -> str:
        return self._label or f"{self.field} == {self.value}"


class MetadataReranker:
    """Adds metadata-derived relevance boosts to a retrieved candidate list."""

    def __init__(self, boosters: Optional[List[MetadataBooster]] = None):
        self.boosters = boosters or []

    def rerank(self, query: str,
               candidates: List[Tuple[Chunk, float]],
               k: Optional[int] = None) -> List[Tuple[Chunk, float]]:
        scored = []
        for chunk, base in candidates:
            bonus = sum(b.boost(chunk.metadata) for b in self.boosters)
            scored.append((chunk, base + bonus))
        scored.sort(key=lambda x: x[1], reverse=True)
        return scored[:k] if k else scored

    def describe(self) -> str:
        return " + ".join(b.label() for b in self.boosters) or "no boosters"


class MMRReranker:
    """Diversity-aware reranking (Maximal Marginal Relevance)."""

    def __init__(self, vectorstore: VectorStore, lambda_mult: float = 0.7):
        self.vectorstore = vectorstore
        self.lambda_mult = lambda_mult

    def rerank(self, query: str,
               candidates: List[Tuple[Chunk, float]],
               k: Optional[int] = None) -> List[Tuple[Chunk, float]]:
        if not candidates:
            return []
        vec_by_id = {c.id: v for c, v in zip(self.vectorstore.chunks,
                                             self.vectorstore.vectors)}
        remaining = list(candidates)
        selected: List[Tuple[Chunk, float]] = []
        while remaining and (k is None or len(selected) < k):
            best, best_mmr = None, float("-inf")
            for chunk, base in remaining:
                if selected:
                    max_sim = max(
                        self.vectorstore.embeddings.cosine(
                            vec_by_id[chunk.id], vec_by_id[c.id])
                        for c, _ in selected
                    )
                else:
                    max_sim = 0.0
                mmr = self.lambda_mult * base - (1.0 - self.lambda_mult) * max_sim
                if mmr > best_mmr:
                    best_mmr, best = mmr, (chunk, base)
            selected.append(best)
            remaining.remove(best)
        return selected

"""Optional production embedding backends.

These adapters are not exercised by the offline demo (no external
dependencies / API keys required there) but demonstrate how to swap the
local vectorizer for a real embedding model.  Each adapter implements the
same interface the pipeline depends on:

    fit(texts), embed_query(text), embed_documents(texts), cosine(a, b)
"""
from __future__ import annotations

import math
from typing import List, Optional


def _dot(a: List[float], b: List[float]) -> float:
    return sum(x * y for x, y in zip(a, b))


def _norm(v: List[float]) -> float:
    return math.sqrt(_dot(v, v))


class OpenAIEmbeddingsAdapter:
    """Adapter for OpenAI's text-embedding models (needs ``openai`` + key)."""

    def __init__(self, model: str = "text-embedding-ada-002",
                 api_key: Optional[str] = None):
        try:
            import openai  # noqa: F401
        except ImportError as exc:  # pragma: no cover
            raise RuntimeError(
                "The 'openai' package is not installed; run `pip install openai`."
            ) from exc
        self._openai = __import__("openai")
        self.model = model
        if api_key:
            self._openai.api_key = api_key

    def fit(self, texts: List[str]) -> None:
        pass  # OpenAI embeddings are zero-shot; nothing to fit

    def embed_query(self, text: str) -> List[float]:
        return self._embed([text])[0]

    def embed_documents(self, texts: List[str]) -> List[List[float]]:
        return self._embed(texts)

    def _embed(self, texts: List[str]) -> List[List[float]]:
        resp = self._openai.Embedding.create(model=self.model, input=texts)
        ordered = sorted(resp["data"], key=lambda d: d["index"])
        return [item["embedding"] for item in ordered]

    @staticmethod
    def cosine(a: List[float], b: List[float]) -> float:
        na, nb = _norm(a), _norm(b)
        return _dot(a, b) / (na * nb) if na and nb else 0.0


class SentenceTransformersAdapter:
    """Adapter for local sentence-transformers models (needs the package)."""

    def __init__(self, model_name: str = "all-MiniLM-L6-v2"):
        try:
            from sentence_transformers import SentenceTransformer  # noqa: F401
        except ImportError as exc:  # pragma: no cover
            raise RuntimeError(
                "The 'sentence-transformers' package is not installed."
            ) from exc
        self._model = SentenceTransformer(model_name)

    def fit(self, texts: List[str]) -> None:
        pass  # pretrained model; no corpus fitting required

    def embed_query(self, text: str) -> List[float]:
        return self._model.encode(text, normalize_embeddings=True).tolist()

    def embed_documents(self, texts: List[str]) -> List[List[float]]:
        return self._model.encode(texts, normalize_embeddings=True).tolist()

    @staticmethod
    def cosine(a: List[float], b: List[float]) -> float:
        return _dot(a, b)  # vectors are L2-normalized already

"""Evaluation metrics for the retrieval + answer pipeline."""
from __future__ import annotations

from typing import Any, Dict, List, Optional, Sequence

from .filters import Filter


def _metadata_of(item: Any) -> Dict[str, Any]:
    if isinstance(item, dict):
        return item.get("metadata", {})
    return getattr(item, "metadata", {})


def precision_at_k(retrieved: Sequence[str], relevant: Sequence[str],
                   k: int = 3) -> float:
    relevant_set = set(relevant)
    top = list(retrieved)[:k]
    if not top:
        return 0.0
    return sum(1 for doc_id in top if doc_id in relevant_set) / len(top)


def recall_at_k(retrieved: Sequence[str], relevant: Sequence[str],
                k: int = 3) -> float:
    relevant_set = set(relevant)
    if not relevant_set:
        return 0.0
    top = list(retrieved)[:k]
    return sum(1 for doc_id in top if doc_id in relevant_set) / len(relevant_set)


def reciprocal_rank(retrieved: Sequence[str], relevant: Sequence[str]) -> float:
    relevant_set = set(relevant)
    for rank, doc_id in enumerate(retrieved, start=1):
        if doc_id in relevant_set:
            return 1.0 / rank
    return 0.0


def filter_compliance(items: Sequence[Any],
                      filter_expr: Optional[Filter]) -> float:
    """Fraction of returned items whose metadata satisfies the filter."""
    if filter_expr is None or not items:
        return 1.0
    ok = sum(1 for item in items if filter_expr.matches(_metadata_of(item)))
    return ok / len(items)


def evaluate_queries(results: List[Dict[str, Any]],
                     relevance: Dict[str, List[str]],
                     k: int = 3) -> Dict[str, float]:
    """Aggregate metrics across query runs.

    ``results``: list of dicts as returned by ``RAGPipeline.answer``.
    ``relevance``: mapping query string -> list of relevant doc ids.
    """
    precisions, recalls, rrs, grounded = [], [], [], []
    for res in results:
        relevant = relevance.get(res.get("query"), [])
        retrieved = [s.get("doc_id") for s in res.get("sources", [])]
        precisions.append(precision_at_k(retrieved, relevant, k))
        recalls.append(recall_at_k(retrieved, relevant, k))
        rrs.append(reciprocal_rank(retrieved, relevant))
        grounded.append(float(res.get("groundedness", 0.0)))
    n = max(1, len(results))
    return {
        f"precision@{k}": round(sum(precisions) / n, 4),
        f"recall@{k}": round(sum(recalls) / n, 4),
        "mrr": round(sum(rrs) / n, 4),
        "avg_groundedness": round(sum(grounded) / n, 4),
    }

#!/usr/bin/env python3
# -*- coding: utf-8 -*-
"""
metadata_rag.py
==============

A self-contained Retrieval-Augmented Generation (RAG) system that uses
**metadata for filtering and ranking** documents by relevance to user queries.

Pipeline overview
-----------------
1. **Ingestion** -- documents are split into chunks; every chunk inherits its
   parent document's metadata (source, category, author, year, priority, tags,
   region, published date, ...) plus a chunk index.
2. **Indexing** -- each chunk is indexed twice:
     * dense: vector embeddings (hashing-trick by default; an optional
       sentence-transformers backend can be swapped in), and
     * sparse: a BM25 lexical index.
3. **Metadata pre-filtering** -- a declarative filter language (exact match,
   range, set membership, substring, existence, and boolean combinations)
   restricts retrieval to eligible chunks *before* scoring.
4. **Hybrid relevance ranking** -- dense cosine similarity fused with BM25
   scores using Reciprocal Rank Fusion (RRF) or weighted z-scores.
5. **Metadata-aware re-ranking** -- priority/category/tag boost rules and
   exponential recency time-decay adjust the fused score; an optional MMR
   (maximal marginal relevance) pass adds diversity.
6. **Generation** -- a grounded, citation-carrying answer is built from the
   top-ranked chunks (extractive by default).  Any LLM callable can be
   injected through ``pipeline.generator`` for synthesis.

The file runs on the Python standard library (>= 3.9) with **no external
dependencies**; `sentence-transformers` is used automatically when available
and requested.

Usage
-----
    python metadata_rag.py          # run the built-in demo + evaluation

    from metadata_rag import RAGPipeline, MetadataBoost, TimeDecay, eq, Contains

    pipe = RAGPipeline()
    pipe.index_document(
        "Atlas API rate limits are 100 requests/min per API key.",
        {"category": "docs", "priority": "high", "year": 2024,
         "tags": ["api", "rate-limit"], "published": "2024-06-01"},
        doc_id="rate-limits",
    )
    boost = MetadataBoost()
    boost.add_rule(eq("priority", "high"), 1.4)
    boost.add_rule(Contains("tags", "search"), 1.2)

    results = pipe.retrieve(
        "how many requests per minute are allowed?",
        metadata_filter={"category": "docs"},
        rank_config=RAGPipeline.default_config(metadata_boost=boost),
    )
    out = pipe.query(
        "how many requests per minute are allowed?",
        metadata_filter={"category": "docs"},
    )
    print(out.answer)
"""

