# ---------------------------------------------------------------------------
# Tokenization
# ---------------------------------------------------------------------------

_WORD_RE = re.compile(r"[A-Za-z0-9_]+(?:['-][A-Za-z0-9_]+)*")
_SENT_RE = re.compile(r"(?<=[.!?])\s+")

_STOPWORDS = frozenset(
    """
    a about above after again against all am an and any are aren't as at be
    because been before being below between both but by can cannot could
    couldn't did didn't do does doesn't doing don't down during each few for
    from further had hadn't has hasn't have haven't having he he'd he'll he's
    her here here's hers herself him himself his how how's i i'd i'll i'm
    i've if in into is isn't it it's its itself let's me more most mustn't my
    myself no nor not of off on once only or other ought our ours ourselves out
    over own same shan't she she'd she'll she's should shouldn't so some such
    than that that's the their theirs them themselves then there there's these
    they they'd they'll they're they've this those through to too under until
    up very was wasn't we we'd we'll we're we've were weren't what what's when
    when's where where's which while who who's whom why why's with won't would
    wouldn't you you'd you'll you're you've your yours yourself yourselves
    """.split()
)


def tokenize(text: Optional[str]) -> List[str]:
    """Lowercase, whitespace/punctuation tokenization with stopword removal."""
    if not text:
        return []
    return [
        t
        for t in _WORD_RE.findall(text.lower())
        if t not in _STOPWORDS and len(t) > 1
    ]


def split_sentences(text: str) -> List[str]:
    """Split text on sentence boundaries, collapsing newlines."""
    return [s.strip() for s in _SENT_RE.split(text.replace("\n", " ")) if s.strip()]


def _stable_hash(token: str, salt: str = "") -> int:
    """Deterministic 64-bit hash for a token (stable across processes)."""
    digest = hashlib.md5((salt + token).encode("utf-8")).digest()
    return int.from_bytes(digest[:8], "big")


def cosine_similarity(a: Sequence[float], b: Sequence[float]) -> float:
    """Cosine similarity between two (ideally pre-normalised) vectors."""
    dot = 0.0
    for x, y in zip(a, b):
        dot += x * y
    return dot


def _normalize(vec: Sequence[float]) -> List[float]:
    n = math.sqrt(sum(v * v for v in vec))
    if n <= 0.0:
        return [0.0] * len(vec)
    return [v / n for v in vec]


def _parse_dt(value: Any) -> datetime.datetime:
    """Coerce datetime / date / ISO-8601 string to a naive datetime."""
    if isinstance(value, datetime.datetime):
        return value
    if isinstance(value, datetime.date):
        return datetime.datetime(value.year, value.month, value.day)
    return datetime.datetime.fromisoformat(str(value).replace("Z", "+00:00"))


