    print(f"\n[ingest] embedder backend: {pipe.embedder.backend}")
    n = pipe.index_documents(_demo_documents())
    print(f"[ingest] indexed {n} chunks from {len(pipe.store.chunks)} documents")

    print("\n--- 1. Metadata PRE-FILTERING: only category=docs is eligible ---")
    res = pipe.retrieve(
        "how do I configure API rate limits for my account?",
        k=3,
        metadata_filter={"category": "docs"},
    )
    _print_results(res)

    print("\n--- 2. RANGE filter (year >= 2023) on timeout question ---")
    res = pipe.retrieve(
        "what happens if my requests time out?",
        k=3,
        metadata_filter={"year": {"gte": 2023}},
    )
    _print_results(res)

    print("\n--- 3. Boolean filter: legal OR docs, excluding changelog ---")
    res = pipe.retrieve(
        "what do you do with my data?",
        k=3,
        metadata_filter={
            "$and": [
                {"category": {"in": ["legal", "docs"]}},
                {"category": {"neq": "changelog"}},
            ]
        },
    )
    _print_results(res)

    print("\n--- 4. METADATA RANKING: recency time-decay (2025 reference) ---")
    recency_config = RankConfig(
        fusion="rrf",
        time_decay=TimeDecay(field="published", reference="2025-06-01", half_life_days=365),
    )
    res = pipe.retrieve("rate limiting policy", k=3, rank_config=recency_config)
    _print_results(res)

    print("\n--- 5. METADATA RANKING: priority/tag boost rules ---")
    boost = MetadataBoost()
    boost.add_rule(eq("priority", "high"), 1.5)
    boost.add_rule(contains("tags", "search"), 1.3)
    boost_config = RankConfig(metadata_boost=boost)
    res = pipe.retrieve(
        "relevance ranking with metadata filters",
        k=3,
        rank_config=boost_config,
    )
    _print_results(res)

    print("\n--- 6. MMR diversity reranking (lambda=0.7) ---")
    res = pipe.retrieve(
        "api documentation webhooks and batching",
        k=3,
        mmr=MMRReranker(lambda_mult=0.7),
    )
    _print_results(res)

    print("\n--- 7. End-to-end grounded answer (with citations) ---")
    out = pipe.query(
        "how do I configure API rate limits for my account?",
        k=2,
        metadata_filter={"category": "docs"},
    )
    print(f"query: {out.query}")
    print(out.answer)

    print("\n--- 8. Evaluation (Hits@3 / MRR) ---")
    cases = [
        {"query": "how do I configure api rate limits", "relevant": ["rate-limits"],
         "filter": {"category": "docs"}},
        {"query": "what are the terms for data retention", "relevant": ["terms", "privacy"]},
        {"query": "timeout errors when calling the api", "relevant": ["timeouts"]},
        {"query": "how to set up webhooks", "relevant": ["webhooks"]},
        {"query": "rate limiting for eu customers", "relevant": ["rate-limit-incident"],
         "filter": {"region": "eu"}},
    ]
    metrics = evaluate(pipe, cases, k=3)
    print(f"  mean Hits@3 : {metrics['mean_hits_at_k']:.3f}")
    print(f"  mean MRR    : {metrics['mean_mrr']:.3f}")
    print(f"  mean latency: {metrics['mean_latency_seconds'] * 1000:.1f} ms")
    for case in metrics["cases"]:
        flag = "OK " if case["hits_at_k"] else "MISS"
        print(f"  [{flag}] {case['query']:<45} top={case['top_ids']}")


if __name__ == "__main__":
    main()

"""
metadata_rag.py
===============

A self-contained Retrieval-Augmented Generation (RAG) system that uses
metadata for BOTH filtering and ranking of documents based on relevance to
user queries.

Features
--------
1. Ingests text documents together with structured metadata (source, author,
   category, date, priority, tags, ...).
2. Splits documents into overlapping chunks; each chunk inherits the parent
   document's metadata.
3. Indexes chunk vectors.  A dependency-free hashing TF embedder is the
   default; pluggable embedders (sentence-transformers, OpenAI) are provided.
4. Filters candidates with metadata predicates BEFORE retrieval, using either
   a small DSL (e.g. ``"category == auth and date >= 2024-02-01"``) or a
   composable ``MetadataFilter`` object.
5. Ranks candidates with a hybrid relevance score:
       score = dense_weight * cosine(query, chunk)
             + sparse_weight * BM25(query, chunk)
             + metadata_boost(chunk.metadata)
6. Aggregates chunk scores to produce ranked *documents* (max or sum).
7. Produces a grounded answer with citations through a pluggable responder;
   the default extractive responder needs no external dependencies.

Everything here uses only the Python standard library unless an optional
embedder/responder is explicitly configured.

Example
-------
    from metadata_rag import Document, RAGPipeline, RAGConfig, parse_metadata_filter

    pipe = RAGPipeline(RAGConfig(top_k=4, dense_weight=0.7, sparse_weight=0.3))
    pipe.add_documents([
        Document(text="...", metadata={"category": "auth", "priority": "high"}),
        Document(text="...", metadata={"category": "billing", "priority": "low"}),
    ])

    result = pipe.query(
        "How do I authenticate API requests?",
        metadata_filter="category == auth",           # metadata filtering
        metadata_boost={"priority": {"high": 0.3}},   # metadata ranking boost
    )
    print(result["answer"])
"""

