            metadata={
                "source": "docs/deploy.md",
                "title": "Deployment Notes",
                "category": "infra",
                "priority": "low",
                "tags": ["devops", "kubernetes", "secrets"],
                "date": "2024-01-15",
            },
            text=(
                "Deploy the service as a Kubernetes Deployment with three replicas "
                "for availability.\n"
                "Set environment variables through a ConfigMap and mount secrets "
