#!/usr/bin/env python3
# -*- coding: utf-8 -*-
"""
metadata_rag.py
==============

A self-contained Retrieval-Augmented Generation (RAG) system that uses
**metadata for filtering and ranking** documents by relevance to user queries.

Pipeline overview
-----------------
1. **Ingestion** -- documents are split into chunks; every chunk inherits its
   parent document's metadata (source, category, author, year, priority, tags,
   region, published date, ...) plus a chunk index.
2. **Indexing** -- each chunk is indexed twice:
     * dense: vector embeddings (hashing-trick by default; an optional
       sentence-transformers backend can be swapped in), and
     * sparse: a BM25 lexical index.
3. **Metadata pre-filtering** -- a declarative filter language (exact match,
   range, set membership, substring, existence, and boolean combinations)
   restricts retrieval to eligible chunks *before* scoring.
4. **Hybrid relevance ranking** -- dense cosine similarity fused with BM25
   scores using Reciprocal Rank Fusion (RRF) or weighted z-scores.
5. **Metadata-aware re-ranking** -- priority/category/tag boost rules and
   exponential recency time-decay adjust the fused score; an optional MMR
   (maximal marginal relevance) pass adds diversity.
6. **Generation** -- a grounded, citation-carrying answer is built from the
   top-ranked chunks (extractive by default).  Any LLM callable can be
   injected through ``pipeline.generator`` for synthesis.

The file runs on the Python standard library (>= 3.9) with **no external
dependencies**; `sentence-transformers` is used automatically when available
and requested.

Usage
-----
    python metadata_rag.py          # run the built-in demo + evaluation

    from metadata_rag import RAGPipeline, MetadataBoost, TimeDecay, eq, Contains

    pipe = RAGPipeline()
    pipe.index_document(
        "Atlas API rate limits are 100 requests/min per API key.",
        {"category": "docs", "priority": "high", "year": 2024,
         "tags": ["api", "rate-limit"], "published": "2024-06-01"},
        doc_id="rate-limits",
    )
    boost = MetadataBoost()
    boost.add_rule(eq("priority", "high"), 1.4)
    boost.add_rule(Contains("tags", "search"), 1.2)

    results = pipe.retrieve(
        "how many requests per minute are allowed?",
        metadata_filter={"category": "docs"},
        rank_config=RAGPipeline.default_config(metadata_boost=boost),
    )
    out = pipe.query(
        "how many requests per minute are allowed?",
        metadata_filter={"category": "docs"},
    )
    print(out.answer)
"""

from __future__ import annotations

import datetime
import hashlib
import math
import re
import statistics
import time
from collections import Counter
from dataclasses import dataclass, field
from typing import (
    Any,
    Callable,
    Dict,
    Iterable,
    List,
    Mapping,
    Optional,
    Sequence,
    Set,
    Tuple,
    Union,
)

__all__ = [
    "Chunk",
    "Chunker",
    "Document",
    "HashEmbedder",
    "AutoEmbedder",
    "BM25Index",
    "InMemoryVectorStore",
    "RankedResult",
    "RankConfig",
    "MetadataBoost",
    "TimeDecay",
    "MMRReranker",
    "RAGPipeline",
    "QueryResult",
    "ExtractiveGenerator",
    "evaluate",
    # filter helpers
    "Expr",
    "eq",
    "neq",
    "gt",
    "gte",
    "lt",
    "lte",
    "in_",
    "not_in",
    "contains",
    "startswith",
    "exists",
    "and_",
    "or_",
    "not_",
    "parse_filter_spec",
]

# ---------------------------------------------------------------------------
# Tokenization
# ---------------------------------------------------------------------------

_WORD_RE = re.compile(r"[A-Za-z0-9_]+(?:['-][A-Za-z0-9_]+)*")
_SENT_RE = re.compile(r"(?<=[.!?])\s+")

_STOPWORDS = frozenset(
    """
    a about above after again against all am an and any are aren't as at be
    because been before being below between both but by can cannot could
    couldn't did didn't do does doesn't doing don't down during each few for
    from further had hadn't has hasn't have haven't having he he'd he'll he's
    her here here's hers herself him himself his how how's i i'd i'll i'm
    i've if in into is isn't it it's its itself let's me more most mustn't my
    myself no nor not of off on once only or other ought our ours ourselves out
    over own same shan't she she'd she'll she's should shouldn't so some such
    than that that's the their theirs them themselves then there there's these
    they they'd they'll they're they've this those through to too under until
    up very was wasn't we we'd we'll we're we've were weren't what what's when
    when's where where's which while who who's whom why why's with won't would
    wouldn't you you'd you'll you're you've your yours yourself yourselves
    """.split()
)


def tokenize(text: Optional[str]) -> List[str]:
    """Lowercase, whitespace/punctuation tokenization with stopword removal."""
    if not text:
        return []
    return [
        t
        for t in _WORD_RE.findall(text.lower())
        if t not in _STOPWORDS and len(t) > 1
    ]


def split_sentences(text: str) -> List[str]:
    """Split text on sentence boundaries, collapsing newlines."""
    return [s.strip() for s in _SENT_RE.split(text.replace("\n", " ")) if s.strip()]


def _stable_hash(token: str, salt: str = "") -> int:
    """Deterministic 64-bit hash for a token (stable across processes)."""
    digest = hashlib.md5((salt + token).encode("utf-8")).digest()
    return int.from_bytes(digest[:8], "big")


def cosine_similarity(a: Sequence[float], b: Sequence[float]) -> float:
    """Cosine similarity between two (ideally pre-normalised) vectors."""
    dot = 0.0
    for x, y in zip(a, b):
        dot += x * y
    return dot


def _normalize(vec: Sequence[float]) -> List[float]:
    n = math.sqrt(sum(v * v for v in vec))
    if n <= 0.0:
        return [0.0] * len(vec)
    return [v / n for v in vec]


def _parse_dt(value: Any) -> datetime.datetime:
    """Coerce datetime / date / ISO-8601 string to a naive datetime."""
    if isinstance(value, datetime.datetime):
        return value
    if isinstance(value, datetime.date):
        return datetime.datetime(value.year, value.month, value.day)
    return datetime.datetime.fromisoformat(str(value).replace("Z", "+00:00"))


# ---------------------------------------------------------------------------
# Core data types
# ---------------------------------------------------------------------------


@dataclass
class Chunk:
    """A retrievable unit of text together with its (inherited) metadata."""

    text: str
    metadata: Dict[str, Any] = field(default_factory=dict)
    chunk_index: int = 0


@dataclass
class Document:
    """An ingested document prior to chunking."""

    text: str
    metadata: Dict[str, Any] = field(default_factory=dict)
    doc_id: Optional[str] = None


@dataclass
class RankedResult:
    """A retrieved chunk with its fused relevance score and per-signal scores."""

    chunk: Chunk
    score: float = 0.0
    dense_score: float = 0.0
    sparse_score: float = 0.0
    rank: int = 0


@dataclass
class QueryResult:
    """The full output of a RAG query: answer + ranked, filtered sources."""

    query: str
    answer: str
    sources: List[RankedResult] = field(default_factory=list)
    elapsed_seconds: float = 0.0
    metadata_filter: Any = None


# ---------------------------------------------------------------------------
# Embeddings
# ---------------------------------------------------------------------------


class HashEmbedder:
    """Deterministic bag-of-tokens embedding using the hashing trick.

    The signed random-projection form yields a fixed-dimensional vector whose
    cosine similarity is a cheap lexical-overlap kernel.  This keeps the demo
    dependency-free; swap in a real embedder for production semantics.
    """

    def __init__(self, dim: int = 512, idf: Optional[Mapping[str, float]] = None):
        self.dim = dim
        self.idf = dict(idf or {})

    def embed(self, text: str) -> List[float]:
        vec = [0.0] * self.dim
        for token, count in Counter(tokenize(text)).items():
            idx = _stable_hash(token) % self.dim
            sign = 1.0 if (_stable_hash(token, "sign") & 1) == 0 else -1.0
            vec[idx] += sign * count * self.idf.get(token, 1.0)
        return _normalize(vec)


class _SentenceTransformerEmbedder:
    """Optional real embedding backend used when the package is installed."""

    def __init__(self, model_name: str = "all-MiniLM-L6-v2"):
        from sentence_transformers import SentenceTransformer  # deferred import

        self.model = SentenceTransformer(model_name)

    def embed(self, text: str) -> List[float]:
        return self.model.encode([text], normalize_embeddings=True)[0].tolist()


class AutoEmbedder:
    """Choose the best available embedder: real model, then hashing fallback."""

    def __init__(
        self,
        prefer: str = "auto",
        dim: int = 512,
        model_name: str = "all-MiniLM-L6-v2",
    ):
        self.backend: str
        if prefer == "hash":
            self._impl = HashEmbedder(dim=dim)
            self.backend = "hash"
        elif prefer in ("auto", "sentence-transformers"):
            try:
                self._impl = _SentenceTransformerEmbedder(model_name)
                self.backend = "sentence-transformers"
            except Exception:
                if prefer == "sentence-transformers":
                    raise
                self._impl = HashEmbedder(dim=dim)
                self.backend = "hash"
        else:
            raise ValueError(f"unknown embedder preference: {prefer!r}")

    def embed(self, text: str) -> List[float]:
        return self._impl.embed(text)


# ---------------------------------------------------------------------------
# Sparse retrieval: BM25
# ---------------------------------------------------------------------------


class BM25Index:
    """Standard Okapi BM25 index over chunk token streams."""

    def __init__(self, k1: float = 1.5, b: float = 0.75):
        self.k1 = k1
        self.b = b
        self._docs: List[Tuple[str, List[str]]] = []
        self._doc_freqs: Dict[str, int] = {}
        self._idf: Dict[str, float] = {}
        self._avgdl: float = 0.0

    def add_document(self, doc_id: str, tokens: Sequence[str]) -> None:
        self._docs.append((doc_id, list(tokens)))
        for token in set(tokens):
            self._doc_freqs[token] = self._doc_freqs.get(token, 0) + 1

    def build(self) -> None:
        n = len(self._docs)
        self._avgdl = sum(len(t) for _, t in self._docs) / n if n else 0.0
        self._idf = {}
        for token, df in self._doc_freqs.items():
            self._idf[token] = math.log(1.0 + (n - df + 0.5) / (df + 0.5))

    def score(self, query_tokens: Sequence[str], doc_tokens: Sequence[str]) -> float:
        if not doc_tokens or not query_tokens:
            return 0.0
        dl = len(doc_tokens)
        tf = Counter(doc_tokens)
        total = 0.0
        for q in set(query_tokens):
            f = tf.get(q, 0)
            if not f:
                continue
            idf = self._idf.get(q, 0.0)
            denom = f + self.k1 * (1.0 - self.b + self.b * dl / self._avgdl) if self._avgdl else 1.0
            total += idf * (f * (self.k1 + 1.0)) / denom
        return total

    def search(
        self, query_tokens: Sequence[str], limit: Optional[int] = None
    ) -> List[Tuple[str, float]]:
        results = [
            (doc_id, self.score(query_tokens, tokens))
            for doc_id, tokens in self._docs
        ]
        results.sort(key=lambda x: x[1], reverse=True)
        return results[:limit] if limit is not None else results


# ---------------------------------------------------------------------------
# Metadata filter expression language
# ---------------------------------------------------------------------------

_MISSING = object()


class Expr:
    """Base class for metadata filter expressions."""

    def matches(self, metadata: Mapping[str, Any]) -> bool:
        raise NotImplementedError

    def __and__(self, other: "Expr") -> "And":
        return And(self, other)

    def __or__(self, other: "Expr") -> "Or":
        return Or(self, other)

    def __invert__(self) -> "Not":
        return Not(self)


class _Field(Expr):
    def __init__(self, field: str):
        self.field = field

    def _value(self, metadata: Mapping[str, Any]) -> Any:
        return metadata.get(self.field, _MISSING)


class Eq(_Field):
    def __init__(self, field: str, value: Any):
        super().__init__(field)
        self.value = value

    def matches(self, metadata: Mapping[str, Any]) -> bool:
        v = self._value(metadata)
        return v is not _MISSING and v == self.value


class Neq(_Field):
    def __init__(self, field: str, value: Any):
        super().__init__(field)
        self.value = value

    def matches(self, metadata: Mapping[str, Any]) -> bool:
        v = self._value(metadata)
        return v is _MISSING or v != self.value


class Gt(_Field):
    def __init__(self, field: str, value: Any):
        super().__init__(field)
        self.value = value

    def matches(self, metadata: Mapping[str, Any]) -> bool:
        v = self._value(metadata)
        if v is _MISSING:
            return False
        try:
            return v > self.value
        except TypeError:
            return False


class Gte(_Field):
    def __init__(self, field: str, value: Any):
        super().__init__(field)
        self.value = value

    def matches(self, metadata: Mapping[str, Any]) -> bool:
        v = self._value(metadata)
        if v is _MISSING:
            return False
        try:
            return v >= self.value
        except TypeError:
            return False


class Lt(_Field):
    def __init__(self, field: str, value: Any):
        super().__init__(field)
        self.value = value

    def matches(self, metadata: Mapping[str, Any]) -> bool:
        v = self._value(metadata)
        if v is _MISSING:
            return False
        try:
            return v < self.value
        except TypeError:
            return False


class Lte(_Field):
    def __init__(self, field: str, value: Any):
        super().__init__(field)
        self.value = value

    def matches(self, metadata: Mapping[str, Any]) -> bool:
        v = self._value(metadata)
        if v is _MISSING:
            return False
        try:
            return v <= self.value
        except TypeError:
            return False


class In(_Field):
    def __init__(self, field: str, values: Iterable[Any]):
        super().__init__(field)
        self.values = set(values)

    def matches(self, metadata: Mapping[str, Any]) -> bool:
        v = self._value(metadata)
        return v is not _MISSING and v in self.values


class NotIn(_Field):
    def __init__(self, field: str, values: Iterable[Any]):
        super().__init__(field)
        self.values = set(values)

    def matches(self, metadata: Mapping[str, Any]) -> bool:
        v = self._value(metadata)
        return v is _MISSING or v not in self.values


class Contains(_Field):
    """Substring test for strings; membership test for lists/sets/tuples."""

    def __init__(self, field: str, value: Any):
        super().__init__(field)
        self.value = value

    def matches(self, metadata: Mapping[str, Any]) -> bool:
        v = self._value(metadata)
        if v is _MISSING:
            return False
        try:
            return self.value in v
        except TypeError:
            return False


class Startswith(_Field):
    def __init__(self, field: str, prefix: str):
        super().__init__(field)
        self.prefix = prefix

    def matches(self, metadata: Mapping[str, Any]) -> bool:
        v = self._value(metadata)
        return isinstance(v, str) and v.startswith(self.prefix)


class Exists(_Field):
    def matches(self, metadata: Mapping[str, Any]) -> bool:
        return self._value(metadata) is not _MISSING


class Not(Expr):
    def __init__(self, inner: Expr):
        self.inner = inner

    def matches(self, metadata: Mapping[str, Any]) -> bool:
        return not self.inner.matches(metadata)


class And(Expr):
    def __init__(self, *exprs: Expr):
        self.exprs = list(exprs)

    def matches(self, metadata: Mapping[str, Any]) -> bool:
        return all(e.matches(metadata) for e in self.exprs)


class Or(Expr):
    def __init__(self, *exprs: Expr):
        self.exprs = list(exprs)

    def matches(self, metadata: Mapping[str, Any]) -> bool:
        return any(e.matches(metadata) for e in self.exprs)


# Functional constructors ---------------------------------------------------

def eq(field: str, value: Any) -> Expr:
    return Eq(field, value)


def neq(field: str, value: Any) -> Expr:
    return Neq(field, value)


def gt(field: str, value: Any) -> Expr:
    return Gt(field, value)


def gte(field: str, value: Any) -> Expr:
    return Gte(field, value)


def lt(field: str, value: Any) -> Expr:
    return Lt(field, value)


def lte(field: str, value: Any) -> Expr:
    return Lte(field, value)


def in_(field: str, values: Iterable[Any]) -> Expr:
    return In(field, values)


def not_in(field: str, values: Iterable[Any]) -> Expr:
    return NotIn(field, values)


def contains(field: str, value: Any) -> Expr:
    return Contains(field, value)


def startswith(field: str, prefix: str) -> Expr:
    return Startswith(field, prefix)


def exists(field: str) -> Expr:
    return Exists(field)


def and_(*exprs: Expr) -> Expr:
    return And(*exprs)


def or_(*exprs: Expr) -> Expr:
    return Or(*exprs)


def not_(expr: Expr) -> Expr:
    return Not(expr)


_OP_MAP: Dict[str, Callable[[str, Any], Expr]] = {
    "eq": eq,
    "neq": neq,
    "gt": gt,
    "gte": gte,
    "lt": lt,
    "lte": lte,
    "in": in_,
    "not_in": not_in,
    "contains": contains,
    "startswith": startswith,
    "exists": lambda f, v: Exists(f) if v else Not(Exists(f)),
}


def parse_filter_spec(spec: Optional[Mapping[str, Any]]) -> Optional[Expr]:
    """Convert a declarative spec into a filter expression.

    Examples
    --------
    {"category": "docs"}
    {"year": {"gte": 2023}}
    {"tags": {"contains": "search"}, "priority": "high"}
    {"$or": [{"category": "docs"}, {"category": "blog"}]}
    """
    if spec is None:
        return None
    parts: List[Expr] = []
    if "$and" in spec:
        parts.append(And(*(parse_filter_spec(s) for s in spec["$and"])))
    if "$or" in spec:
        parts.append(Or(*(parse_filter_spec(s) for s in spec["$or"])))
    for key, value in spec.items():
        if key in ("$and", "$or"):
            continue
        if isinstance(value, Mapping):
            for op, operand in value.items():
                if op not in _OP_MAP:
                    raise ValueError(f"unknown filter operator: {op!r}")
                parts.append(_OP_MAP[op](key, operand))
        else:
            parts.append(Eq(key, value))
    if not parts:
        return None
    return parts[0] if len(parts) == 1 else And(*parts)


# ---------------------------------------------------------------------------
# Chunking
# ---------------------------------------------------------------------------


class Chunker:
    """Recursive separator-based chunker with overlap."""

    def __init__(
        self,
        chunk_size: int = 800,
        chunk_overlap: int = 160,
        separators: Sequence[str] = ("\n\n", "\n", " "),
    ):
        if chunk_overlap >= chunk_size:
            raise ValueError("chunk_overlap must be smaller than chunk_size")
        self.chunk_size = chunk_size
        self.chunk_overlap = chunk_overlap
        self.separators = list(separators)

    def split(self, text: str, metadata: Optional[Mapping[str, Any]] = None) -> List[Chunk]:
        pieces = self._split_text(text)
        base_meta = dict(metadata or {})
        chunks = []
        for i, piece in enumerate(pieces):
            meta = dict(base_meta)
            meta["chunk_index"] = i
            meta["chunk_count"] = len(pieces)
            chunks.append(Chunk(text=piece, metadata=meta, chunk_index=i))
        return chunks

    def _split_text(self, text: str) -> List[str]:
        if len(text) <= self.chunk_size:
            return [text]
        pieces: List[str] = []
        cursor = text
        while len(cursor) > self.chunk_size:
            cut = self._find_cut(cursor)
            pieces.append(cursor[:cut])
            if cut <= self.chunk_overlap:
                cursor = cursor[cut:]
            else:
                cursor = cursor[cut - self.chunk_overlap :]
        if cursor:
            pieces.append(cursor)
        return pieces

    def _find_cut(self, text: str) -> int:
        window = text[: self.chunk_size]
        best = self.chunk_size
        for sep in self.separators:
            idx = window.rfind(sep)
            if idx > self.chunk_size // 2:
                best = idx + len(sep)
                break
        return best


# ---------------------------------------------------------------------------
# Metadata-aware ranking configuration
# ---------------------------------------------------------------------------


class MetadataBoost:
    """Rules that multiply a chunk's fused score based on its metadata."""

    def __init__(self):
        self._rules: List[Tuple[Expr, float]] = []

    def add_rule(self, condition: Expr, factor: float) -> "MetadataBoost":
        if factor < 0.0:
            raise ValueError("boost factors must be non-negative")
        self._rules.append((condition, factor))
        return self

    def factor(self, metadata: Mapping[str, Any]) -> float:
        total = 1.0
        for condition, factor in self._rules:
            if condition.matches(metadata):
                total *= factor
        return total


@dataclass
class TimeDecay:
    """Exponential recency decay: recent documents are preferred."""

    field: str
    reference: str  # ISO date string used as "now"
    half_life_days: float = 365.0

    def factor(self, metadata: Mapping[str, Any]) -> float:
        raw = metadata.get(self.field)
        if raw is None:
            return 1.0
        try:
            age_days = max(0.0, (_parse_dt(self.reference) - _parse_dt(raw)).total_seconds() / 86400.0)
        except (TypeError, ValueError):
            return 1.0
        return math.exp(-math.log(2.0) * age_days / self.half_life_days)


@dataclass
class RankConfig:
    """Configuration for hybrid fusion + metadata-aware re-ranking."""

    dense_weight: float = 0.5
    sparse_weight: float = 0.5
    fusion: str = "rrf"  # "rrf" or "weighted"
    rrf_k: int = 60
    metadata_boost: Optional[MetadataBoost] = None
    time_decay: Optional[TimeDecay] = None

    def __post_init__(self) -> None:
        if self.fusion not in ("rrf", "weighted"):
            raise ValueError(f"unknown fusion strategy: {self.fusion!r}")


class MMRReranker:
    """Diversity reranking via maximal marginal relevance."""

    def __init__(self, lambda_mult: float = 0.7):
        if not 0.0 <= lambda_mult <= 1.0:
            raise ValueError("lambda_mult must be within [0, 1]")
        self.lambda_mult = lambda_mult

    def rerank(
        self,
        results: Sequence[RankedResult],
        k: int,
        vector_of: Callable[[RankedResult], Sequence[float]],
    ) -> List[RankedResult]:
        if len(results) <= k:
            return list(results)
        pool = list(results)
        selected: List[RankedResult] = []
        while len(selected) < k and pool:
            best_idx = 0
            best_value = -math.inf
            for i, candidate in enumerate(pool):
                relevance = candidate.score
                max_sim = 0.0
                for chosen in selected:
                    sim = cosine_similarity(vector_of(candidate), vector_of(chosen))
                    if sim > max_sim:
                        max_sim = sim
                value = self.lambda_mult * relevance - (1.0 - self.lambda_mult) * max_sim
                if value > best_value:
                    best_value = value
                    best_idx = i
            selected.append(pool.pop(best_idx))
        return selected


# ---------------------------------------------------------------------------
# In-memory vector store with metadata filtering + hybrid ranking
# ---------------------------------------------------------------------------


class InMemoryVectorStore:
    """Holds chunks, dense vectors and BM25 terms; executes filtered search."""

    def __init__(self, embedder: Any, chunker: Optional[Chunker] = None):
        self.embedder = embedder
        self.chunker = chunker or Chunker()
        self.chunk_ids: List[str] = []
        self.chunks: List[Chunk] = []
        self.vectors: List[List[float]] = []
        self.tokenized: List[List[str]] = []
        self.bm25 = BM25Index()

    def add_document(
        self,
        text: str,
        metadata: Optional[Mapping[str, Any]] = None,
        doc_id: Optional[str] = None,
        chunk: bool = True,
    ) -> int:
        meta = dict(metadata or {})
        if doc_id is not None:
            meta.setdefault("doc_id", doc_id)
        if chunk:
            chunks = self.chunker.split(text, meta)
        else:
            chunks = [Chunk(text=text, metadata=meta)]
        for c in chunks:
            cid = f"{doc_id or 'doc'}-{len(self.chunks)}"
            if doc_id is not None:
                cid = f"{doc_id}::c{c.chunk_index}"
            self.chunk_ids.append(cid)
            self.chunks.append(c)
            self.vectors.append(self.embedder.embed(c.text))
            self.tokenized.append(tokenize(c.text))
            self.bm25.add_document(cid, self.tokenized[-1])
        self.bm25.build()
        return len(chunks)

    def add_documents(
        self, docs: Iterable[Document], chunk: bool = True
    ) -> int:
        total = 0
        for doc in docs:
            total += self.add_document(doc.text, doc.metadata, doc.doc_id, chunk=chunk)
        return total

    def _candidate_indices(self, filter_expr: Optional[Expr]) -> List[int]:
        if filter_expr is None:
            return list(range(len(self.chunks)))
        return [
            i
            for i, chunk in enumerate(self.chunks)
            if filter_expr.matches(chunk.metadata)
        ]

    def search(
        self,
        query: str,
        k: int = 5,
        filter_expr: Optional[Expr] = None,
        config: Optional[RankConfig] = None,
        mmr: Optional[MMRReranker] = None,
    ) -> List[RankedResult]:
        config = config or RankConfig()
        query_vec = self.embedder.embed(query)
        q_tokens = tokenize(query)
        indices = self._candidate_indices(filter_expr)
        if not indices:
            return []

        # --- dense scores (cosine similarity over pre-normalised vectors) ---
        dense_scores: Dict[int, float] = {
            i: cosine_similarity(query_vec, self.vectors[i]) for i in indices
        }
        dense_ranked = sorted(dense_scores, key=dense_scores.get, reverse=True)

        # --- sparse scores (BM25) ---
        sparse_scores: Dict[int, float] = {}
        for i in indices:
            s = self.bm25.score(q_tokens, self.tokenized[i])
            if s > 0.0:
                sparse_scores[i] = s
        sparse_ranked = sorted(sparse_scores, key=sparse_scores.get, reverse=True)

        # --- fusion ---
        fused: Dict[int, float] = {}
        if config.fusion == "rrf":
            for rank, i in enumerate(dense_ranked):
                fused[i] = fused.get(i, 0.0) + config.dense_weight / (config.rrf_k + rank + 1)
            for rank, i in enumerate(sparse_ranked):
                fused[i] = fused.get(i, 0.0) + config.sparse_weight / (config.rrf_k + rank + 1)
        else:  # weighted z-score normalisation
            zd = self._zscore(dense_ranked, dense_scores)
            zs = self._zscore(sparse_ranked, sparse_scores)
            for i in set(dense_ranked) | set(sparse_ranked):
                fused[i] = (
                    config.dense_weight * zd.get(i, -1.0)
                    + config.sparse_weight * zs.get(i, -1.0)
                )

        # --- metadata-aware re-ranking (boost rules + recency decay) ---
        for i in list(fused):
            meta = self.chunks[i].metadata
            multiplier = 1.0
            if config.metadata_boost is not None:
                multiplier *= config.metadata_boost.factor(meta)
            if config.time_decay is not None:
                multiplier *= config.time_decay.factor(meta)
            fused[i] *= multiplier

        ranked = sorted(fused, key=fused.get, reverse=True)
        results = [
            RankedResult(
                chunk=self.chunks[i],
                score=fused[i],
                dense_score=dense_scores.get(i, 0.0),
                sparse_score=sparse_scores.get(i, 0.0),
            )
            for i in ranked
        ]

        if mmr is not None:
            vec_by_chunk = {id(c): v for c, v in zip(self.chunks, self.vectors)}
            results = mmr.rerank(results, k, lambda r: vec_by_chunk[id(r.chunk)])

        return results[:k]

    @staticmethod
    def _zscore(
        ranked: Sequence[int], scores: Mapping[int, float]
    ) -> Dict[int, float]:
        if not ranked:
            return {}
        values = [scores[i] for i in ranked]
        mean = sum(values) / len(values)
        sd = statistics.pstdev(values) if len(values) > 1 else 0.0
        if sd == 0.0:
            return {i: 0.0 for i in ranked}
        return {i: (scores[i] - mean) / sd for i in ranked}


# ---------------------------------------------------------------------------
# Generation
# ---------------------------------------------------------------------------


class ExtractiveGenerator:
    """Grounds an answer in retrieved chunks and returns citations.

    Sentences are selected only when they share query terms, so the answer is
    directly attributable to the retrieved (and metadata-filtered) documents.
    """

    def __init__(self, max_sentences: int = 6, max_context_chars: int = 1600):
        self.max_sentences = max_sentences
        self.max_context_chars = max_context_chars

    def generate(
        self, query: str, results: Sequence[RankedResult]
    ) -> Tuple[str, List[Tuple[int, str]]]:
        q_terms = set(tokenize(query))
        citations: List[Tuple[int, str]] = []
        used: Set[str] = set()
        budget = self.max_context_chars
        for idx, result in enumerate(results, start=1):
            if budget <= 0 or len(citations) >= self.max_sentences:
                break
            for sentence in split_sentences(result.chunk.text):
                if len(citations) >= self.max_sentences:
                    break
                if sentence in used:
                    continue
                if q_terms and not (set(tokenize(sentence)) & q_terms):
                    continue
                used.add(sentence)
                citations.append((idx, sentence))
                budget -= len(sentence)
        if not citations:
            answer = (
                "I could not find enough information in the retrieved "
                "documents to answer the question."
            )
            return answer, []

        parts = []
        for idx, sentence in citations:
            source = results[idx - 1].chunk.metadata.get("source", "unknown")
            parts.append(f"[{idx}] ({source}) {sentence}")
        answer = (
            "Based on the retrieved documents:\n"
            + "\n".join(parts)
            + "\n\n(Extractive answer generated from retrieved chunks; attach an "
              "LLM callable via pipeline.generator for a synthesized response.)"
        )
        return answer, citations


# ---------------------------------------------------------------------------
# Pipeline
# ---------------------------------------------------------------------------


class RAGPipeline:
    """High-level RAG pipeline: index -> filter -> rank -> generate."""

    def __init__(
        self,
        embedder: Optional[Any] = None,
        chunker: Optional[Chunker] = None,
        generator: Optional[Any] = None,
        rank_config: Optional[RankConfig] = None,
    ):
        self.embedder = embedder or AutoEmbedder()
        self.chunker = chunker or Chunker()
        self.store = InMemoryVectorStore(self.embedder, self.chunker)
        self.generator = generator or ExtractiveGenerator()
        self.rank_config = rank_config or RankConfig()

    @staticmethod
    def default_config(**overrides: Any) -> RankConfig:
        return RankConfig(**overrides)

    # -- indexing ----------------------------------------------------------

    def index_document(
        self,
        text: str,
        metadata: Optional[Mapping[str, Any]] = None,
        doc_id: Optional[str] = None,
        chunk: bool = True,
    ) -> int:
        return self.store.add_document(text, metadata, doc_id, chunk=chunk)

    def index_documents(self, docs: Iterable[Document], chunk: bool = True) -> int:
        return self.store.add_documents(docs, chunk=chunk)

    # -- retrieval ---------------------------------------------------------

    def retrieve(
        self,
        query: str,
        k: int = 5,
        metadata_filter: Optional[Union[Expr, Mapping[str, Any]]] = None,
        rank_config: Optional[RankConfig] = None,
        mmr: Optional[MMRReranker] = None,
    ) -> List[RankedResult]:
        expr = (
            metadata_filter
            if isinstance(metadata_filter, Expr)
            else parse_filter_spec(metadata_filter)
        )
        results = self.store.search(
            query,
            k=k,
            filter_expr=expr,
            config=rank_config or self.rank_config,
            mmr=mmr,
        )
        for i, result in enumerate(results):
            result.rank = i
        return results

    # -- end-to-end question answering ------------------------------------

    def query(
        self,
        query: str,
        k: int = 5,
        metadata_filter: Optional[Union[Expr, Mapping[str, Any]]] = None,
        rank_config: Optional[RankConfig] = None,
        mmr: Optional[MMRReranker] = None,
        generate: bool = True,
    ) -> QueryResult:
        started = time.perf_counter()
        results = self.retrieve(query, k=k, metadata_filter=metadata_filter,
                                rank_config=rank_config, mmr=mmr)
        if generate:
            answer, _ = self.generator.generate(query, results)
        else:
            answer = ""
        return QueryResult(
            query=query,
            answer=answer,
            sources=results,
            elapsed_seconds=time.perf_counter() - started,
            metadata_filter=metadata_filter,
        )


# ---------------------------------------------------------------------------
# Evaluation
# ---------------------------------------------------------------------------


def _retrieved_doc_ids(results: Sequence[RankedResult]) -> List[str]:
    return [r.chunk.metadata.get("doc_id") for r in results if r.chunk.metadata.get("doc_id")]


def hits_at_k(retrieved: Sequence[RankedResult], relevant: Iterable[str], k: int) -> bool:
    ids = set(_retrieved_doc_ids(retrieved[:k]))
    return bool(ids & set(relevant))


def mrr(retrieved: Sequence[RankedResult], relevant: Iterable[str]) -> float:
    relevant_set = set(relevant)
    for rank, doc_id in enumerate(_retrieved_doc_ids(retrieved), start=1):
        if doc_id in relevant_set:
            return 1.0 / rank
    return 0.0


def evaluate(
    pipeline: RAGPipeline,
    cases: Sequence[Mapping[str, Any]],
    k: int = 3,
    rank_config: Optional[RankConfig] = None,
) -> Dict[str, Any]:
    """Evaluate Hits@k and MRR over labeled query cases.

    Each case is a mapping with keys: "query", "relevant" (doc ids), and an
    optional "filter" (metadata filter spec).
    """
    hits: List[float] = []
    mrrs: List[float] = []
    latencies: List[float] = []
    per_case: List[Dict[str, Any]] = []
    for case in cases:
        started = time.perf_counter()
        results = pipeline.retrieve(
            case["query"],
            k=k,
            metadata_filter=case.get("filter"),
            rank_config=rank_config,
        )
        elapsed = time.perf_counter() - started
        relevant = case.get("relevant", [])
        h = 1.0 if hits_at_k(results, relevant, k) else 0.0
        m = mrr(results, relevant)
        hits.append(h)
        mrrs.append(m)
        latencies.append(elapsed)
        per_case.append(
            {
                "query": case["query"],
                "hits_at_k": h,
                "mrr": m,
                "elapsed_seconds": elapsed,
                "top_ids": _retrieved_doc_ids(results[:k]),
            }
        )
    return {
        "mean_hits_at_k": sum(hits) / len(hits) if hits else 0.0,
        "mean_mrr": sum(mrrs) / len(mrrs) if mrrs else 0.0,
        "mean_latency_seconds": sum(latencies) / len(latencies) if latencies else 0.0,
        "cases": per_case,
    }


