# ---------------------------------------------------------------------------
# Text utilities
# ---------------------------------------------------------------------------

_TOKEN_RE = re.compile(r"[a-zA-Z0-9_]+")
_STOPWORDS = frozenset(
    """a an and are as at be by for from has he her his i in is it its of on or
    she that the their they this to was were will with""".split()
)


def tokenize(text: str, remove_stopwords: bool = False) -> List[str]:
    """Lowercase tokenizer for the lexical scoring layer."""
    if not text:
        return []
    text = unicodedata.normalize("NFKC", text).lower()
    tokens = _TOKEN_RE.findall(text)
    if remove_stopwords:
        return [t for t in tokens if t not in _STOPWORDS]
    return tokens


def _flatten(value: Any) -> List[Any]:
    """Return a list view of a metadata value (scalar or list-like)."""
    if isinstance(value, (list, tuple, set)):
        return list(value)
    return [value]


def _cmp_value(value: Any) -> Any:
    """Coerce ISO date-like strings to comparable date/datetime objects."""
    if isinstance(value, str):
        text = value.strip()
        for parser in (date.fromisoformat, datetime.fromisoformat):
            try:
                return parser(text)
            except ValueError:
                continue
    return value


def _compare_any(values: Iterable[Any], target: Any, op: Callable[[Any, Any], bool]) -> bool:
    """Apply a comparison operator to any matching metadata value."""
    target = _cmp_value(target)
    for value in values:
        lhs = _cmp_value(value)
        try:
            if op(lhs, target):
                return True
        except TypeError:  # incompatible types (e.g. str vs int)
            continue
    return False


def _cosine(a: Sequence[float], b: Sequence[float]) -> float:
    if not a or not b or len(a) != len(b):
        return 0.0
    dot = sum(x * y for x, y in zip(a, b))
    na = math.sqrt(sum(x * x for x in a)) or 1.0
    nb = math.sqrt(sum(x * x for x in b)) or 1.0
    return dot / (na * nb)


def _mean(xs: Sequence[float]) -> float:
    return sum(xs) / len(xs) if xs else 0.0


