def _print_results(header: str, result: Dict[str, Any]) -> None:
    print(f"\n=== {header} ===")
    print(f"Question: {result['question']}")
    print(f"Answer: {result['answer']}")
    print("Ranked results (chunk level):")
    for scored in result["results"]:
        metadata_summary = {
            k: scored.chunk.metadata[k]
            for k in ("category", "priority", "date", "source")
            if k in scored.chunk.metadata
        }
        print(
            f"  #{scored.rank} {scored.chunk.id:>14}  score={scored.score:6.3f} "
            f"(dense={scored.dense_score:5.3f}, sparse={scored.sparse_score:5.3f}, "
            f"boost={scored.metadata_boost:4.2f})  {metadata_summary}"
        )


def main() -> None:
    pipe = RAGPipeline(RAGConfig(chunk_size=400, chunk_overlap=60, top_k=3))
    num_chunks = pipe.add_documents(_sample_documents())
    print(f"Indexed {num_chunks} chunks from {len(_sample_documents())} documents")

    # 1. Plain retrieval (no metadata filter).
    _print_results(
        "Query 1: no metadata filter",
        pipe.query("How do I authenticate API requests?"),
    )

    # 2. Metadata filtering: only the auth category is considered.
    _print_results(
        "Query 2: metadata_filter='category == auth'",
        pipe.query("How do I authenticate API requests?", metadata_filter="category == auth"),
    )

    # 3. Metadata filtering with a date range + membership test.
    _print_results(
        "Query 3: filter='date >= 2024-02-01 and category in (auth, billing)'",
        pipe.query(
            "Which endpoints handle refunds?",
            metadata_filter="date >= 2024-02-01 and category in (auth, billing)",
        ),
    )

    # 4. Metadata used for RANKING: boost high-priority documents.
    _print_results(
        "Query 4: metadata_boost={'priority': {'high': 0.3}}",
        pipe.query(
            "How do I authenticate API requests?",
            metadata_boost={"priority": {"high": 0.3}},
        ),
    )

    # 5. Document-level ranking (chunk scores aggregated by doc_id).
    print("\n=== Document-level ranking for 'How do I authenticate API requests?' ===")
    for doc_id, score, results in pipe.retrieve_documents(
        "How do I authenticate API requests?", top_k=3
    ):
        print(f"  {doc_id:>16}  aggregated_score={score:6.3f}  ({len(results)} chunks)")

    # 6. Evaluation with labeled relevance judgments.
    cases = [
        ("How do I authenticate API requests?", ["auth-guide"]),
        ("Which endpoints handle refunds?", ["billing-api"]),
        ("How do I deploy the service?", ["deployment-notes"]),
    ]
    metrics = evaluate_retrieval(pipe, cases, k=3)
    print("\n=== Retrieval evaluation (labeled cases) ===")
    for name, value in metrics.items():
        print(f"  {name}: {value:.3f}")


if __name__ == "__main__":
    main()
